const SENTINEL_FACTS=["The Sentinelese are believed to have lived in isolation on North Sentinel Island for tens of thousands of years, possibly since the first human migrations out of Africa.","North Sentinel Island covers only about 59.67 sq. km, roughly the size of a small town, yet has remained almost entirely unexplored by outsiders.","Surrounding coral reefs make the island's coastline treacherous to approach by boat, which has helped keep it isolated for centuries.","The Sentinelese reportedly moved to higher ground before the 2004 Indian Ocean tsunami struck, an example of traditional ecological knowledge passed down without any written record.","India has enforced a strict 'eyes-on, hands-off' no-contact policy toward the island since the late 1990s.","The Protection of Aboriginal Tribes Regulation, 1956 makes it illegal to travel to North Sentinel Island or attempt contact with its residents.","No outside census has ever been conducted on the island; population estimates of roughly 50 to 200 people come from aerial and offshore observation only."];let factIndex=0;function initTabs(){const e=document.querySelectorAll(".sentinel-tab-btn"),t=document.querySelectorAll(".sentinel-tab-panel");e.forEach(n=>{n.addEventListener("click",()=>{const o=n.getAttribute("data-tab");e.forEach(e=>e.classList.remove("active")),n.classList.add("active"),t.forEach(e=>{e.classList.toggle("active",e.id==="tab-"+o)})})})}function initFactsRotator(){const e=document.getElementById("sentinel-fact-text"),t=document.getElementById("sentinel-fact-dots");function n(n){factIndex=n,e.style.opacity="0",setTimeout(()=>{e.textContent=SENTINEL_FACTS[factIndex],e.style.opacity="1"},200),t&&[...t.children].forEach((e,t)=>e.classList.toggle("active",t===factIndex))}e&&(t&&SENTINEL_FACTS.forEach((e,o)=>{const a=document.createElement("button");a.className="sentinel-fact-dot"+(0===o?" active":""),a.setAttribute("aria-label","Show fact "+(o+1)),a.addEventListener("click",()=>n(o)),t.appendChild(a)}),n(0),setInterval(()=>n((factIndex+1)%SENTINEL_FACTS.length),6e3))}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initFactsRotator()});